17	package org.springframework.samples.petclinic.rest.controller;
18	
19	import org.springframework.samples.petclinic.model.Owner;
20	import org.springframework.samples.petclinic.service.ClinicService;
21	import org.springframework.samples.petclinic.util.HashUtils;
22	import org.springframework.samples.petclinic.util.IdentityUtils;
23	import org.springframework.stereotype.Component;
24	
25	/**
26	 * Owns the household-identity concern: the single place that decides which owners belong to
27	 * the same household and derives the shared household id they carry.
28	 *
29	 * <p>Keeping this in one place means the shared household id and the household-membership
30	 * lookup can never drift apart: two owners belong to the same household exactly when the
31	 * identity fields this resolver keys on (their normalized last name and address) agree, and
32	 * for that household they derive an identical id.
33	 *
34	 * <p>The household id is formatted {@code 'HH-<HEX12>'} where HEX12 is the first twelve
35	 * upper-case hex characters of the SHA-256 digest of the normalized last name and address
36	 * joined by '|'.
37	 */
38	@Component
39	public class HouseholdResolver {
40	
41	    private final ClinicService clinicService;
42	
43	    private final AddressNormalizer addressNormalizer;
44	
45	    public HouseholdResolver(ClinicService clinicService, AddressNormalizer addressNormalizer) {
46	        this.clinicService = clinicService;
47	        this.addressNormalizer = addressNormalizer;
48	    }
49	
50	    /**
51	     * The stable, shared household identifier for {@code owner}. Owners in the same household
52	     * (same normalized last name and address) derive an identical id.
53	     *
54	     * @param owner the owner whose household id is derived; its address is read in the same
55	     *              canonical form used for household comparison
56	     * @return the {@code 'HH-<HEX12>'} household id
57	     */
58	    public String householdId(Owner owner) {
59	        String key = IdentityUtils.normalizeIdentity(owner.getLastName()) + "|" + addressKey(owner);
60	        return "HH-" + HashUtils.sha256HexPrefix(key, 12);
61	    }
62	
63	    /**
64	     * Whether an existing owner already belongs to {@code owner}'s household, so an owner
65	     * flagged {@code sharesHousehold} has a household to join.
66	     *
67	     * @param owner the owner about to be created
68	     * @return {@code true} if an already-registered owner shares this owner's household
69	     */
70	    public boolean householdExists(Owner owner) {
71	        String lastNameKey = IdentityUtils.normalizeIdentity(owner.getLastName());
72	        String addressKey = addressKey(owner);
73	        return this.clinicService.findAllOwners().stream()
74	            .anyMatch(existing -> IdentityUtils.normalizeIdentity(existing.getLastName()).equals(lastNameKey)
75	                && addressKey(existing).equals(addressKey));
76	    }
77	
78	    /** The owner's address in the canonical form under which households are compared. */
79	    private String addressKey(Owner owner) {
80	        return addressNormalizer.normalize(owner.getAddress());
81	    }
82	}
