17	package org.springframework.samples.petclinic.util;
18	
19	import java.nio.charset.StandardCharsets;
20	import java.security.MessageDigest;
21	import java.security.NoSuchAlgorithmException;
22	import java.util.Locale;
23	
24	/**
25	 * Small stateless helpers for the SHA-256 hex derivations that back the application's
26	 * identity values (customer codes, household ids).
27	 *
28	 * <p>Keeping the derivation in one place means every identity value built from a truncated
29	 * hex digest reads the same computation and they can never drift apart.
30	 */
31	public abstract class HashUtils {
32	
33	    /**
34	     * The first {@code length} upper-case hex characters of the SHA-256 digest of the UTF-8
35	     * bytes of {@code source}.
36	     *
37	     * @param source the string to digest
38	     * @param length the number of leading hex characters to return
39	     * @return the first {@code length} upper-case hex characters of the SHA-256 digest
40	     */
41	    public static String sha256HexPrefix(String source, int length) {
42	        try {
43	            byte[] digest = MessageDigest.getInstance("SHA-256")
44	                .digest(source.getBytes(StandardCharsets.UTF_8));
45	            StringBuilder sb = new StringBuilder(digest.length * 2);
46	            for (byte b : digest) {
47	                sb.append(String.format("%02x", b));
48	            }
49	            return sb.substring(0, length).toUpperCase(Locale.ROOT);
50	        }
51	        catch (NoSuchAlgorithmException e) {
52	            throw new IllegalStateException("SHA-256 not available", e);
53	        }
54	    }
55	}
