16	
17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.LocalDate;
20	import java.util.Collection;
21	import java.util.List;
22	import java.util.Locale;
23	import java.util.regex.Pattern;
24	
25	import org.slf4j.Logger;
26	import org.slf4j.LoggerFactory;
27	import org.springframework.http.HttpHeaders;
28	import org.springframework.http.HttpStatus;
29	import org.springframework.http.ResponseEntity;
30	import org.springframework.samples.petclinic.mapper.OwnerMapper;
31	import org.springframework.samples.petclinic.mapper.PetMapper;
32	import org.springframework.samples.petclinic.mapper.VisitMapper;
33	import org.springframework.samples.petclinic.model.Owner;
34	import org.springframework.samples.petclinic.model.Pet;
35	import org.springframework.samples.petclinic.model.Visit;
36	import org.springframework.samples.petclinic.rest.api.OwnersApi;
37	import org.springframework.samples.petclinic.rest.controller.AddressNormalizer;
38	import org.springframework.samples.petclinic.rest.controller.CityRegionResolver;
39	import org.springframework.samples.petclinic.rest.controller.HouseholdResolver;
40	import org.springframework.samples.petclinic.rest.controller.TelephoneNormalizer;
41	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
42	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
43	import org.springframework.samples.petclinic.rest.dto.PetDto;
44	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
45	import org.springframework.samples.petclinic.rest.dto.VisitDto;
46	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
47	import org.springframework.samples.petclinic.service.ClinicService;
48	import org.springframework.samples.petclinic.util.HashUtils;
49	import org.springframework.samples.petclinic.util.IdentityUtils;
50	import org.springframework.security.access.prepost.PreAuthorize;
51	import org.springframework.web.bind.annotation.CrossOrigin;
52	import org.springframework.web.bind.annotation.RequestMapping;
53	import org.springframework.web.bind.annotation.RestController;
54	import org.springframework.web.util.UriComponentsBuilder;
55	
56	import jakarta.transaction.Transactional;
57	
58	/**
59	 * @author Vitaliy Fedoriv
60	 */
61	
62	@RestController
63	@CrossOrigin(exposedHeaders = "errors, content-type")
64	@RequestMapping("/api")
65	public class OwnerRestControllerV1 implements OwnersApi {
66	
67	    /** Minimal syntactic check for an email address: a non-empty local part, a single
68	     *  '@', and a dotted domain, none containing whitespace or a second '@'. */
69	    private static final Pattern EMAIL_PATTERN =
70	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
71	
72	    /** A postcode, when supplied, must be exactly four digits before its region range is checked. */
73	    private static final Pattern POSTCODE_PATTERN = Pattern.compile("^[0-9]{4}$");
74	
75	    /** Dedicated audit logger; emits an audit line on successful owner create. */
76	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
77	
78	    private final ClinicService clinicService;
79	
80	    private final OwnerMapper ownerMapper;
81	
82	    private final PetMapper petMapper;
83	
84	    private final VisitMapper visitMapper;
85	
86	    private final TelephoneNormalizer telephoneNormalizer;
87	
88	    private final AddressNormalizer addressNormalizer;
89	
90	    private final CityRegionResolver cityRegionResolver;
91	
92	    private final HouseholdResolver householdResolver;
93	
94	    public OwnerRestControllerV1(ClinicService clinicService,
95	                                 OwnerMapper ownerMapper,
96	                                 PetMapper petMapper,
97	                                 VisitMapper visitMapper,
98	                                 TelephoneNormalizer telephoneNormalizer,
99	                                 AddressNormalizer addressNormalizer,
100	                                 CityRegionResolver cityRegionResolver,
101	                                 HouseholdResolver householdResolver) {
102	        this.clinicService = clinicService;
103	        this.ownerMapper = ownerMapper;
104	        this.petMapper = petMapper;
105	        this.visitMapper = visitMapper;
106	        this.telephoneNormalizer = telephoneNormalizer;
107	        this.addressNormalizer = addressNormalizer;
108	        this.cityRegionResolver = cityRegionResolver;
109	        this.householdResolver = householdResolver;
110	    }
111	
112	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
113	    @Override
114	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
115	        Collection<Owner> owners;
116	        if (lastName != null) {
117	            owners = this.clinicService.findOwnerByLastName(lastName);
118	        } else {
119	            owners = this.clinicService.findAllOwners();
120	        }
121	        if (owners.isEmpty()) {
122	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
123	        }
124	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
125	    }
126	
127	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
128	    @Override
129	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
130	        Owner owner = this.clinicService.findOwnerById(ownerId);
131	        if (owner == null) {
132	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
133	        }
134	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
135	    }
136	
137	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
138	    @Override
139	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
140	        HttpHeaders headers = new HttpHeaders();
141	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
142	        if (owner.getRegistrationDate() == null) {
143	            owner.setRegistrationDate(LocalDate.now());
144	        }
145	        // A supplied registration date may not be later than the server's current date.
146	        if (owner.getRegistrationDate().isAfter(LocalDate.now())) {
147	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
148	        }
149	        owner.setRegistrationDate(toBusinessDay(owner.getRegistrationDate()));
150	        LocalDate registrationDate = owner.getRegistrationDate();
151	        long ownersCreatedThatDay = this.clinicService.findAllOwners().stream()
152	            .map(Owner::getRegistrationDate)
153	            .filter(registrationDate::equals)
154	            .count();
155	        if (ownersCreatedThatDay >= 100) {
156	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
157	        }
158	        String address = addressNormalizer.normalize(owner.getAddress());
159	        if (address.isBlank()) {
160	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
161	        }
162	        owner.setAddress(address);
163	        String telephone = telephoneNormalizer.normalize(owner.getTelephone());
164	        if (telephone == null) {
165	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
166	        }
167	        if (!telephoneNormalizer.hasValidNationalNumberLength(telephone)) {
168	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
169	        }
170	        owner.setTelephone(telephone);
171	        String email = owner.getEmail();
172	        if (email != null) {
173	            email = email.trim();
174	            if (!EMAIL_PATTERN.matcher(email).matches()) {
175	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
176	            }
177	            owner.setEmail(email.toLowerCase(Locale.ROOT));
178	        }
179	        // A postcode is optional, but when supplied it must be four digits and valid for the
180	        // owner's city per the fixed region table; a city with no known region accepts any
181	        // 4-digit postcode. Reject an out-of-range or malformed postcode with 400.
182	        String postcode = owner.getPostcode();
183	        if (postcode != null) {
184	            if (!POSTCODE_PATTERN.matcher(postcode).matches()
185	                    || !cityRegionResolver.isPostcodeValidForCity(owner.getCity(), postcode)) {
186	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
187	            }
188	        }
189	        // The owner's telephone and email are now in their canonical, stored form.
190	        // Establish the household id before the duplicate check so the candidate's whole
191	        // identity key can be compared against the existing owners': only an owner that
192	        // deliberately shares an existing household (same normalized last name and address)
193	        // is assigned that household's shared id; a plain new owner has no household id, so
194	        // its identity key is decided by telephone and email alone.
195	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())
196	                && householdResolver.householdExists(owner)) {
197	            owner.setHouseholdId(householdResolver.householdId(owner));
198	        }
199	        if (isDuplicateOwner(owner)) {
200	            return new ResponseEntity<>(HttpStatus.CONFLICT);
201	        }
202	        String cityKey = IdentityUtils.normalizeIdentity(owner.getCity());
203	        long ownersInCity = this.clinicService.findAllOwners().stream()
204	            .filter(existing -> IdentityUtils.normalizeIdentity(existing.getCity()).equals(cityKey))
205	            .count();
206	        if (ownersInCity >= 50) {
207	            return new ResponseEntity<>(HttpStatus.CONFLICT);
208	        }
209	        owner.setCustomerCode(customerCode(owner));
210	        owner.setNamesakeCount(namesakeCount(owner));
211	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
212	        owner.setBulkSignupWarning(ownersCreatedThatDay > 80);
213	        // Soft-match: the candidate has already cleared the hard-duplicate check, but it may
214	        // still share an existing owner's last name and postcode while carrying a different
215	        // telephone. When it does, it is created but flagged as a possible duplicate of that
216	        // existing owner; otherwise the flag is false and no reference is recorded.
217	        Integer possibleDuplicateOf = possibleDuplicateOf(owner);
218	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
219	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
220	        this.clinicService.saveOwner(owner);
221	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
222	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
223	            ownerMapper.membershipLevel(owner));
224	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
225	        headers.setLocation(UriComponentsBuilder.newInstance()
226	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
227	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
228	    }
229	
230	    /**
231	     * Whether {@code candidate} collides with an already-registered owner under the single
232	     * identity rule enforced on create. This is the one point at which a new owner is
233	     * rejected as a duplicate (HTTP 409): all duplicate detection is consolidated into the
234	     * derived {@link OwnerMapper#identityKey identityKey} — the normalized telephone, the
235	     * email (or an empty string when absent) and the householdId joined by '|'. The
236	     * candidate clashes only when its WHOLE identityKey equals an existing owner's; because
237	     * the telephone is part of the key, two members of the same household (same householdId)
238	     * with different telephones have different identityKeys and are both allowed.
239	     *
240	     * <p>The candidate arrives with its telephone and email already normalized and its
241	     * household id already derived, and each existing owner is stored in the same canonical
242	     * form, so an identityKey match means the two owners are genuinely the same identity.
243	     *
244	     * @param candidate the fully-normalized owner about to be created
245	     * @return {@code true} if an existing owner already occupies the candidate's identityKey
246	     */
247	    private boolean isDuplicateOwner(Owner candidate) {
248	        String identityKey = OwnerMapper.identityKey(candidate);
249	        return this.clinicService.findAllOwners().stream()
250	            .map(OwnerMapper::identityKey)
251	            .anyMatch(identityKey::equals);
252	    }
253	
254	    /**
255	     * The id of the existing owner the fully-normalized {@code candidate} soft-matches, or
256	     * {@code null} when there is none. A soft match is an owner that is not a hard duplicate
257	     * (its whole identityKey differs) yet shares the candidate's normalized last name and its
258	     * postcode while carrying a different telephone — a likely re-registration of the same
259	     * person under a new number. Both must supply a postcode for a match to be possible; when
260	     * several existing owners qualify the lowest id is returned so the result is deterministic.
261	     *
262	     * @param candidate the fully-normalized owner about to be created
263	     * @return the matching existing owner's id, or {@code null} if the candidate is no soft match
264	     */
265	    private Integer possibleDuplicateOf(Owner candidate) {
266	        String postcode = candidate.getPostcode();
267	        if (postcode == null) {
268	            return null;
269	        }
270	        String lastNameKey = IdentityUtils.normalizeIdentity(candidate.getLastName());
271	        return this.clinicService.findAllOwners().stream()
272	            .filter(existing -> IdentityUtils.normalizeIdentity(existing.getLastName()).equals(lastNameKey)
273	                && postcode.equals(existing.getPostcode())
274	                && !postcode.isBlank()
275	                && !java.util.Objects.equals(candidate.getTelephone(), existing.getTelephone()))
276	            .map(Owner::getId)
277	            .filter(java.util.Objects::nonNull)
278	            .min(Integer::compareTo)
279	            .orElse(null);
280	    }
281	
282	    /**
283	     * Build the customer code assigned to {@code owner} on create, formatted
284	     * {@code '<REGION>-<HASH8>'}: REGION is the region code derived from the owner's postcode
285	     * (falling back to the city) via {@link CityRegionResolver}, and HASH8 is the first eight
286	     * upper-case hex characters of the SHA-256 digest of the normalized telephone concatenated
287	     * with the last name (e.g. 'NSW-1A2B3C4D'). There is no per-city sequence.
288	     */
289	    private String customerCode(Owner owner) {
290	        String region = cityRegionResolver.regionFor(owner.getCity(), owner.getPostcode());
291	        String hash8 = HashUtils.sha256HexPrefix(owner.getTelephone() + owner.getLastName(), 8);
292	        return region + "-" + hash8;
293	    }
294	
295	    /**
296	     * The number of existing owners that share {@code owner}'s firstName and lastName,
297	     * compared case-insensitively. The candidate is not yet stored at the point this is
298	     * assigned, so it does not count itself. This is the value stored as the owner's
299	     * namesakeCount on create.
300	     */
301	    private int namesakeCount(Owner owner) {
302	        return (int) this.clinicService.findAllOwners().stream()
303	            .filter(existing -> owner.getFirstName().equalsIgnoreCase(existing.getFirstName())
304	                && owner.getLastName().equalsIgnoreCase(existing.getLastName()))
305	            .count();
306	    }
307	
308	    /**
